(function(){
  let particles=[];
  const N=70;
  for(let i=0;i<N;i++){
    particles.push({
      x: Math.random()*W(),
      y: Math.random()*H(),
      r: Math.random()*1.4+0.4,
      speedY: Math.random()*0.12+0.04,
      speedX: (Math.random()-0.5)*0.08,
      phase: Math.random()*Math.PI*2,
      alphaBase: Math.random()*0.35+0.15
    });
  }
  let rays=[];
  const RN=5;
  for(let i=0;i<RN;i++){
    rays.push({
      angle: (-28 + i*14) * Math.PI/180,
      length: H()*0.55,
      width: 35+Math.random()*35,
      speed: 0.00025+Math.random()*0.00018,
      phase: Math.random()*Math.PI*2
    });
  }
  function hexToRgba(hex,a){
    hex=hex.replace('#','');
    const r=parseInt(hex.substring(0,2),16);
    const g=parseInt(hex.substring(2,4),16);
    const b=parseInt(hex.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }
  function draw(t){
    const w=W(), h=H();
    ctx.clearRect(0,0,w,h);
    ctx.save();
    for(const ray of rays){
      const pulse=0.5+0.5*Math.sin(t*ray.speed+ray.phase);
      const grad=ctx.createLinearGradient(0,0,0,ray.length);
      grad.addColorStop(0,hexToRgba(PALETTE[0],0.16*pulse));
      grad.addColorStop(1,hexToRgba(PALETTE[0],0));
      ctx.save();
      ctx.translate(w*0.12,-h*0.05);
      ctx.rotate(ray.angle);
      ctx.fillStyle=grad;
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(ray.width,0);
      ctx.lineTo(ray.width*0.28,ray.length);
      ctx.lineTo(-ray.width*0.28,ray.length);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
    const cx=w/2, cy=h/2, safeR=Math.min(w,h)*0.3;
    for(const p of particles){
      p.y-=p.speedY;
      p.x+=p.speedX+Math.sin(t*0.0005+p.phase)*0.04;
      if(p.y<-10)p.y=h+10;
      if(p.x<-10)p.x=w+10;
      if(p.x>w+10)p.x=-10;
      const dx=p.x-cx, dy=p.y-cy;
      const dist=Math.sqrt(dx*dx+dy*dy);
      let alpha=p.alphaBase;
      if(dist<safeR){ alpha*=(dist/safeR)*0.25; }
      const flicker=0.6+0.4*Math.sin(t*0.001+p.phase*3);
      ctx.beginPath();
      ctx.fillStyle=hexToRgba(PALETTE[2],alpha*flicker);
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
